css:
@page {
    size: A4;
    margin: 5mm;
}
.right { text-align: right; }
.bold { font-weight: bold; }
.no-border { border: none !important; }

.print-container {
    font-family: Arial, sans-serif;
    font-size: 10px !important;
    color: #000;
}

.outer-table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
}

.outer-table td {
    border: 1px solid #000;
    vertical-align: top;
    padding: 4px;
}

.header-center h2 {
   
    margin: 0;
    text-align: center;
    text-decoration: none;
}

.header-center p {
    font-size: 9px;
    margin: 0;
    text-align: center;
}

.company-info {
    width: 50%;
    vertical-align: top;
    font-size: 12px;
}

.logo-placeholder {
    width: 120px;
    height: 40px;
    border: 1px solid #ccc;
    display: inline-block;
    text-align: center;
    line-height: 40px;
    font-size: 8px;
    margin-bottom: 5px;
    background: #f9f9f9;
}

.details-col {
    font-family: Arial, sans-serif;
    font-size: 10px;
    color: #000;
    vertical-align: top;
    padding: 6px;
    border-left: 1px solid #000;
    border-right: 1px solid #000;
    border-top: 1px solid #000;
    border-bottom: none;
}

.details-col p {
    margin: 2px 0;
    padding: 0;
}


.details-col strong {
    display: inline-block;
    width: 150px;         /* fixed width for labels */
}

.details-col .value {
    margin-left: 10px;    /* space between label and value */
}


.oa-section {
    padding: 10px;
    border-bottom: none;
}

.oa-container {
    display: flex;
    justify-content: flex-start;
    gap: 50px;
    font-size: 10px;
    line-height: 1.5;
}

.oa-labels {
    display: flex;
    flex-direction: column;
    gap: 4px;
    font-weight: bold;
}

.oa-values {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.address-block {
    font-family: Arial, sans-serif;
    font-size: 10px;
    color: #000;
    border-left: 1px solid #000;
    border-right: 1px solid #000;
    border-top: none;
    border-bottom: 1px solid #000;
    padding: 4px;
}
.irn{
   font-size: 10px; 
}

.items-table {
    width: 100%;
    border-collapse: collapse;
}

.items-table th, .items-table td {
    border: 1px solid #000;
    padding: 4px;
    font-size: 10px;
    text-align: center;
}

.items-table th {
    background: #f0f0f0;
    font-weight: bold;
}

.items-table td:nth-child(3) {
    text-align: left;
}

.gst-container {
    width: 50%;
    margin: 5px 0;
}

.gst-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
}

.gst-table th,
.gst-table td {
    border: 1px solid #000;
    padding: 4px;
    text-align: center;
}

.gst-table th {
    background: #f4f4f4;
    font-weight: bold;
}

.gst-heading {
    text-align: left;
    background: #fff;
    border: none;
    font-weight: bold;
    font-size: 11px;
}

.bank-details, .signature-block {
    font-size: 10px;
}

.grand_total {
    font-size: 12px;
    font-weight: bold;
}

.payment_term {
    font-size: 10px;
    font-weight: bold;
}

.signature-space {
    height: 10px;
}

.message {
    text-align: center;
    font-size: 10px;
}

.footer-line {
    text-align: left;
    font-size: 9px;
    font-weight: bold;
    padding: 4px;
}


@media print {
  body { margin: 0; }
  .invoice-container { border: none; }
  thead { display: table-header-group; }
  table { page-break-inside: avoid; }
}
